// Roll raw recall lines up to firm level and score each firm 0-100.
// Mirrors the disclosed rubric in atlas-signal-engine/score.py.
const payload = $input.first().json;
const records = payload.results || [];
if (!records.length) {
  throw new Error('openFDA returned no records — refusing to emit an empty queue');
}

const ANCHOR = new Date();
const firms = new Map();

for (const r of records) {
  const name = (r.recalling_firm || '').trim();
  if (!name) continue;
  if (!firms.has(name)) {
    firms.set(name, { firm: name, events: new Set(), lines: 0, worst: 'Class III', mostRecent: null, ongoing: false, qualityFlag: false, reasons: [], country: r.country || '', state: r.state || '' });
  }
  const f = firms.get(name);
  f.lines += 1;
  if (r.event_id) f.events.add(r.event_id);

  const rank = { 'Class I': 3, 'Class II': 2, 'Class III': 1 };
  if ((rank[r.classification] || 0) > (rank[f.worst] || 0)) f.worst = r.classification;

  const d = r.report_date ? new Date(`${r.report_date.slice(0,4)}-${r.report_date.slice(4,6)}-${r.report_date.slice(6,8)}`) : null;
  if (d && (!f.mostRecent || d > f.mostRecent)) f.mostRecent = d;

  if ((r.status || '').toLowerCase() === 'ongoing') f.ongoing = true;

  const reason = (r.reason_for_recall || '').toLowerCase();
  if (/cgmp|steril|impurit|contamina|assay|dissolution|degradation|stability/.test(reason)) {
    f.qualityFlag = true;
  }
  if (r.reason_for_recall && f.reasons.length < 1) f.reasons.push(r.reason_for_recall);
}

const out = [];
for (const f of firms.values()) {
  const severity = f.worst === 'Class I' ? 40 : f.worst === 'Class II' ? 25 : 10;
  const days = f.mostRecent ? Math.floor((ANCHOR - f.mostRecent) / 86400000) : 9999;
  const recency = days < 30 ? 25 : days < 90 ? 18 : days < 180 ? 10 : 0;
  const n = f.events.size;
  const systemic = n >= 10 ? 20 : n >= 4 ? 14 : n >= 2 ? 8 : 0;
  const quality = f.qualityFlag ? 10 : 0;
  const ongoing = f.ongoing ? 5 : 0;
  const score = severity + recency + systemic + quality + ongoing;

  out.push({ json: {
    firm: f.firm,
    score,
    components: { severity, recency, systemic, quality_system: quality, ongoing },
    worst_classification: f.worst,
    distinct_events: n,
    total_recall_lines: f.lines,
    days_since_recent: days,
    any_ongoing: f.ongoing,
    quality_system_flag: f.qualityFlag,
    representative_reason: f.reasons[0] || '',
    country: f.country,
    state: f.state
  }});
}

out.sort((a, b) => b.json.score - a.json.score);
return out;

// Compose a grounded outreach brief. Every fact below is copied from the
// FDA record — nothing is generated, inferred, or embellished.
// No contact is invented: outreach targets a ROLE, never a named person.
const rows = $input.all();
// HARD CAP: never emit more than 10 briefs per run, however many firms
// clear the threshold. A deliberate volume guard on a daily job — so a bad
// FDA day cannot dump 80 briefs into the queue. Documented in the README.
const briefs = rows.slice(0, 10).map(({ json: f }) => {
  const urgency = f.days_since_recent < 30 ? 'this month' : f.days_since_recent < 90 ? 'this quarter' : 'recently';
  return { json: {
    firm: f.firm,
    score: f.score,
    target_role: 'Chief Quality Officer / VP Quality',
    why_now: `${f.worst_classification} enforcement action ${urgency} (${f.days_since_recent}d ago), ${f.distinct_events} distinct event(s) across ${f.total_recall_lines} recall line(s).`,
    evidence: f.representative_reason.slice(0, 220),
    quality_system_signal: f.quality_system_flag,
    still_ongoing: f.any_ongoing,
    grounded_in: 'openFDA drug/enforcement — every field above is copied verbatim from the filing',
    contact: 'ROLE ONLY — no individual contact is generated by this workflow'
  }};
});
if (!briefs.length) {
  return [{ json: { status: 'no_firms_cleared_threshold', briefs: 0 } }];
}
return briefs;

// Fetch failed after all retries. Emit a structured alert payload rather
// than letting the run die silently — the whole point of the error branch.
const err = $input.first().json;
return [{ json: {
  alert: true,
  severity: 'FAIL',
  workflow: 'FDA Signal → Scored Outreach Queue',
  stage: 'Fetch openFDA Enforcement',
  message: 'openFDA fetch failed after 3 retries — outreach queue NOT refreshed today',
  detail: (err && (err.error || err.message)) || 'unknown error',
  at: new Date().toISOString(),
  action: 'Queue is stale. Do not send from it until this clears.'
}}];
